const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '!vendor' -g '!node_modules' -g '!**/.git/**' | head -40",workdir:"/app",max_output_tokens:1000}),
  tools.exec_command({cmd:"rg -n 'segmentKey|segmentKeys|segmentOperator|SegmentKey|SegmentKeys|SegmentOperator' --glob '!internal/ext/common.go' --glob '!internal/ext/importer.go' --glob '!internal/ext/exporter.go' --glob '!internal/storage/fs/snapshot.go' --glob '!internal/storage/sql/common/rule.go' --glob '!internal/storage/sql/common/rollout.go' --glob '!vendor/**' --glob '!**/.git/**' .",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"rg -n -C 8 'segment:' build/testing/integration/readonly/testdata/default.yaml build/testing/integration/readonly/testdata/production.yaml",workdir:"/app",max_output_tokens:6000})
]);
for (let i=0;i<r.length;i++) text(JSON.stringify({task:i,result:r[i]}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -not -path './.git/*' -not -path './vendor/*' -print",workdir:"/app",max_output_tokens:1000}),
  tools.exec_command({cmd:"grep -RInE 'segmentKey|segmentKeys|segmentOperator|SegmentKey|SegmentKeys|SegmentOperator' --exclude-dir=.git --exclude-dir=vendor --exclude=common.go --exclude=importer.go --exclude=exporter.go --exclude=snapshot.go --exclude=rule.go --exclude=rollout.go .",workdir:"/app",max_output_tokens:10000}),
  tools.exec_command({cmd:"grep -n -A 10 -B 10 'segment:' build/testing/integration/readonly/testdata/default.yaml build/testing/integration/readonly/testdata/production.yaml",workdir:"/app",max_output_tokens:6000}),
  tools.exec_command({cmd:"cat .codex-role-output/checkpoint.md",workdir:"/app",max_output_tokens:1000})
]);
for (let i=0;i<r.length;i++) text(JSON.stringify({task:i,result:r[i]}));

